export const envelope = [32, 20, 32];

export default function build(api) {
  const W = api.size[0];
  const H = api.size[1];
  const D = api.size[2];

  const cx = (W - 1) / 2;
  const cz = (D - 1) / 2;

  const pavement = api.theme.ground.pavement;
  const kerb = api.theme.ground.kerb;
  const coping = api.theme.ground.coping;

  const resin = "minecraft:purpur_block";
  const chitin = "minecraft:bone_block";
  const cyanLight = "minecraft:sea_lantern";

  function put(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  const terrain = new Array(W * D);
  const traceCells = [];
  const padRadius = 7;
  const padRadiusSquared = padRadius * padRadius;
  let minHeight = Infinity;

  for (let x = 0; x < W; x += 1) {
    for (let z = 0; z < D; z += 1) {
      const dx = x - cx;
      const dz = z - cz;
      const r2 = dx * dx + dz * dz;

      if (r2 <= padRadiusSquared) {
        const h = Math.floor(api.heightAt(x, z));
        terrain[x * D + z] = h;
        traceCells.push([x, z, h, r2]);
        if (h < minHeight) {
          minHeight = h;
        }
      }
    }
  }

  const seatY = Math.max(0, Math.min(H - 1, -minHeight));

  function localGround(x, z) {
    let y = seatY + terrain[x * D + z];
    if (y < 0) {
      y = 0;
    }
    if (y >= H) {
      y = H - 1;
    }
    return y;
  }

  for (let i = 0; i < traceCells.length; i += 1) {
    const cell = traceCells[i];
    const x = cell[0];
    const z = cell[1];
    const r2 = cell[3];
    const groundY = localGround(x, z);

    for (let y = 0; y <= groundY; y += 1) {
      put(x, y, z, pavement);
    }

    let top = pavement;
    if (r2 > 36) {
      top = kerb;
    } else if (r2 > 16) {
      top = coping;
    }
    put(x, groundY, z, top);
  }

  const profiles = [
    [7, 4, 3],
    [8, 8, 6],
    [9, 12, 9],
    [10, 15, 11],
    [11, 15, 12],
    [12, 15, 12],
    [13, 15, 12],
    [14, 14, 11],
    [15, 12, 9],
    [16, 9, 7],
    [17, 6, 5],
    [18, 3, 3]
  ];

  for (let p = 0; p < profiles.length; p += 1) {
    const y = profiles[p][0];
    const rx = profiles[p][1];
    const rz = profiles[p][2];

    const minX = Math.max(0, Math.ceil(cx - rx));
    const maxX = Math.min(W - 1, Math.floor(cx + rx));
    const minZ = Math.max(0, Math.ceil(cz - rz));
    const maxZ = Math.min(D - 1, Math.floor(cz + rz));

    for (let x = minX; x <= maxX; x += 1) {
      for (let z = minZ; z <= maxZ; z += 1) {
        const dx = (x - cx) / rx;
        const dz = (z - cz) / rz;
        const q = dx * dx + dz * dz;

        if (q <= 1) {
          let block = resin;

          if (y <= 8 || y === 11 || y === 14 || y >= 16 || q > 0.86) {
            block = chitin;
          }

          if (q > 0.82 && ((x * 7 + z * 11 + y) % 5 === 0)) {
            block = resin;
          }

          if (y === 12 && q > 0.78 && ((x * 5 + z * 3) % 9 === 0)) {
            block = cyanLight;
          }

          if (
            y === 18 &&
            Math.abs(x - cx) <= 1 &&
            Math.abs(z - cz) <= 1
          ) {
            block = cyanLight;
          }

          put(x, y, z, block);
        }
      }
    }
  }

  const beamX0 = Math.floor(cx);
  const beamZ0 = Math.floor(cz);
  const undersideY = 7;

  for (let x = beamX0; x <= beamX0 + 1; x += 1) {
    for (let z = beamZ0; z <= beamZ0 + 1; z += 1) {
      const groundY = localGround(x, z);
      const startY = Math.min(groundY, undersideY);
      const endY = Math.max(groundY, undersideY);

      for (let y = startY; y <= endY; y += 1) {
        put(x, y, z, cyanLight);
      }
    }
  }

  const landingX = beamX0 - 6;
  const landingY = localGround(landingX, beamZ0);

  return {
    name: "Alien Command Vessel",
    seatY: seatY,
    anchors: {
      landing: [landingX, landingY, beamZ0],
      beam: [beamX0, undersideY, beamZ0]
    }
  };
}

alien_drop_pod.source:
export const envelope = [11, 10, 9];

export default function build(api) {
  const W = 11;
  const H = 10;
  const D = 9;
  const seatY = 2;

  const index = api.instance.index;
  const count = api.instance.count;

  const rLeanX = api.random();
  const rLeanZ = api.random();
  const rCap = api.random();
  const rDamage = api.random();
  const rPhase = api.random();
  const rMarker = api.random();
  const rDebris = api.random();
  const rScorch = api.random();

  function mod(value, modulus) {
    const remainder = value % modulus;
    if (remainder < 0) {
      return remainder + modulus;
    }
    return remainder;
  }

  const resin = "minecraft:purpur_block";
  const chitin = "minecraft:bone_block";
  const light = "minecraft:sea_lantern";
  const cyanPanel = "minecraft:cyan_concrete";
  const scorch = mod(index + Math.floor(rScorch * 2), 2) === 0
    ? "minecraft:obsidian"
    : "minecraft:crying_obsidian";

  const foundation = api.theme.ground.plinth;
  const pavement = api.theme.ground.pavement;
  const scar = api.theme.ground.scree;
  const timberLog = api.theme.wood.log;
  const timberPlanks = api.theme.wood.planks;

  const tiltX = mod(index + Math.floor(rLeanX * 3), 3) - 1;
  const tiltZ = mod(index * 2 + Math.floor(rLeanZ * 3), 3) - 1;
  const capMode = mod(index + Math.floor(rCap * 3), 3);
  const phase = index * 47 + count * 13 + Math.floor(rPhase * 997);

  const serialSlot = mod(index, 18);
  const serialX = 10;
  const serialY = serialSlot < 9 ? 2 : 6;
  const serialZ = serialSlot % 9;

  const collarX0 = 4 + tiltX;
  const collarX1 = 9 + tiltX;
  const collarZ0 = 1 + tiltZ;
  const collarZ1 = 7 + tiltZ;

  let capX0;
  let capX1;
  let capZ0;
  let capZ1;

  if (capMode === 0) {
    capX0 = collarX0 + 1;
    capX1 = collarX1 - 1;
    capZ0 = collarZ0 + 1;
    capZ1 = collarZ1 - 1;
  } else if (capMode === 1) {
    capX0 = collarX0 + 1;
    capX1 = collarX1 - 1;
    capZ0 = collarZ0 + 2;
    capZ1 = collarZ1 - 2;
  } else {
    capX0 = collarX0 + 2;
    capX1 = collarX1 - 1;
    capZ0 = collarZ0 + 1;
    capZ1 = collarZ1 - 1;
  }

  const capWidth = capX1 - capX0 + 1;
  const markerCount = 1 + mod(index + Math.floor(rMarker * 5), 5);

  const terrain = new Array(W);
  const floorLevel = new Array(W);

  for (let x = 0; x < W; x += 1) {
    terrain[x] = new Array(D);
    floorLevel[x] = new Array(D);

    for (let z = 0; z < D; z += 1) {
      const value = api.heightAt(x, z);
      terrain[x][z] = value;

      let groundY = seatY + Math.floor(value);
      if (groundY < 0) {
        groundY = 0;
      }
      if (groundY > seatY) {
        groundY = seatY;
      }
      floorLevel[x][z] = groundY;
    }
  }

  function voidCell(x, y, z) {
    if (y < 3 || y > 5) {
      return false;
    }

    const room = x >= 6 && x <= 8 && z >= 3 && z <= 5;
    const hatchTunnel = x >= 3 && x <= 5 && z === 4;

    return room || hatchTunnel;
  }

  function insideHull(x, y, z) {
    if (y >= 0 && y <= 2) {
      return x >= 2 && x <= 10 && z >= 0 && z <= 8;
    }

    if (y >= 3 && y <= 5) {
      return x >= 3 && x <= 10 && z >= 0 && z <= 8 &&
        !voidCell(x, y, z);
    }

    if (y === 6 || y === 7) {
      return x >= 3 && x <= 10 && z >= 0 && z <= 8;
    }

    if (y === 8) {
      return x >= collarX0 && x <= collarX1 &&
        z >= collarZ0 && z <= collarZ1;
    }

    if (y === 9) {
      return x >= capX0 && x <= capX1 &&
        z >= capZ0 && z <= capZ1;
    }

    return false;
  }

  function coordKey(x, y, z) {
    return x + "|" + y + "|" + z;
  }

  function hullTexture(x, y, z) {
    const terrainTerm = Math.floor(terrain[x][z]);
    const pattern = mod(
      x * 17 + y * 11 + z * 13 + phase + terrainTerm * 7,
      9
    );

    if (pattern < 3) {
      return chitin;
    }
    return resin;
  }

  function seamCell(x, y, z) {
    const terrainTerm = Math.floor(terrain[x][z]);

    if (
      y === 3 &&
      (z === 0 || z === 8) &&
      mod(x + y + phase + terrainTerm, 5) === 0
    ) {
      return true;
    }

    if (
      y === 3 &&
      x === 10 &&
      mod(z * 2 + y + phase + terrainTerm, 4) === 0
    ) {
      return true;
    }

    if (
      y === 8 &&
      (x === collarX0 || x === collarX1 ||
        z === collarZ0 || z === collarZ1) &&
      mod(x * 3 + z * 5 + phase + terrainTerm, 4) === 0
    ) {
      return true;
    }

    if (
      y === 9 &&
      mod(
        (x - capX0) * 3 +
        (z - capZ0) * 5 +
        phase,
        4
      ) === 0
    ) {
      return true;
    }

    if (
      y === 3 &&
      x === 3 &&
      (z === 3 || z === 5) &&
      mod(y + z + phase, 2) === 0
    ) {
      return true;
    }

    return false;
  }

  function bodyMaterial(x, y, z) {
    const edge = x === 2 || x === 10 || z === 0 || z === 8;

    if (y < seatY) {
      if (edge) {
        if (y < floorLevel[x][z]) {
          return foundation;
        }
        return pavement;
      }
      return hullTexture(x, y, z);
    }

    if (x === serialX && y === serialY && z === serialZ) {
      return cyanPanel;
    }

    if (y === seatY && edge) {
      const ringPattern = mod(x * 3 + z * 5 + phase, 7);
      if (ringPattern < 2) {
        return scorch;
      }
      return scar;
    }

    if (
      y === 3 &&
      x === 3 &&
      (z === 3 || z === 5)
    ) {
      if (mod(y + z + phase, 3) === 0) {
        return light;
      }
      return chitin;
    }

    if (y === 9) {
      const localIndex =
        (x - capX0) + (z - capZ0) * capWidth;

      if (localIndex < markerCount) {
        return cyanPanel;
      }
    }

    if (seamCell(x, y, z)) {
      return light;
    }

    return hullTexture(x, y, z);
  }

  const damageBudget =
    4 + mod(index, 4) + Math.floor(rDamage * 3);

  const damageCandidates = [];

  for (let y = 3; y <= 5; y += 1) {
    for (let x = 3; x <= 10; x += 1) {
      for (let z = 0; z <= 8; z += 1) {
        const outerFace =
          x === 3 || x === 10 || z === 0 || z === 8;

        if (outerFace && insideHull(x, y, z)) {
          damageCandidates.push([x, y, z]);
        }
      }
    }
  }

  const damaged = new Set();

  if (damageCandidates.length > 0) {
    const damageSpan = Math.max(
      1,
      damageCandidates.length - damageBudget + 1
    );
    const damageStart = mod(
      Math.floor(rDamage * 100000) + index * 17,
      damageSpan
    );

    for (let i = 0; i < damageBudget; i += 1) {
      const candidateIndex = mod(
        damageStart + i * 13,
        damageCandidates.length
      );
      const candidate = damageCandidates[candidateIndex];
      damaged.add(coordKey(candidate[0], candidate[1], candidate[2]));
    }
  }

  const placed = new Set();

  function put(x, y, z, block) {
    if (
      x < 0 || x >= W ||
      y < 0 || y >= H ||
      z < 0 || z >= D
    ) {
      return;
    }

    const key = coordKey(x, y, z);
    if (placed.has(key)) {
      return;
    }

    placed.add(key);
    api.set(x, y, z, block);
  }

  for (let y = 0; y < H; y += 1) {
    for (let x = 0; x < W; x += 1) {
      for (let z = 0; z < D; z += 1) {
        if (!insideHull(x, y, z)) {
          continue;
        }

        if (damaged.has(coordKey(x, y, z))) {
          continue;
        }

        put(x, y, z, bodyMaterial(x, y, z));
      }
    }
  }

  function supportColumn(x, z, topBlock) {
    for (let y = 0; y <= seatY; y += 1) {
      let block = topBlock;

      if (y !== seatY) {
        if (y < floorLevel[x][z]) {
          block = foundation;
        } else {
          block = pavement;
        }
      }

      put(x, y, z, block);
    }
  }

  for (let x = 0; x <= 2; x += 1) {
    let pathBlock = scar;

    if (x === 2) {
      pathBlock = scar;
    } else if (mod(x + phase, 4) === 0) {
      pathBlock = scorch;
    }

    supportColumn(x, 4, pathBlock);

    if (x < 2) {
      let sideZ = 3;

      if (
        mod(
          x + index + Math.floor(rLeanX * 3),
          2
        ) !== 0
      ) {
        sideZ = 5;
      }

      let sideBlock = scar;
      if (mod(x + phase, 3) === 0) {
        sideBlock = scorch;
      }

      supportColumn(x, sideZ, sideBlock);
    }
  }

  const debrisSpots = [
    [1, 3],
    [0, 4],
    [1, 5],
    [0, 3],
    [0, 5]
  ];

  const debrisCount =
    3 + mod(index + Math.floor(rDebris * 3), 3);

  for (let i = 0; i < debrisCount; i += 1) {
    const spot = debrisSpots[i];
    const x = spot[0];
    const z = spot[1];

    let mark = scar;
    if (mod(i + phase, 4) === 0) {
      mark = scorch;
    }

    supportColumn(x, z, mark);

    let lowerDebris = timberLog;
    if (i % 2 !== 0) {
      lowerDebris = timberPlanks;
    }

    put(x, seatY + 1, z, lowerDebris);

    if (mod(i + index + Math.floor(rDebris * 7), 3) === 0) {
      let upperDebris = timberPlanks;
      if (i % 2 !== 0) {
        upperDebris = timberLog;
      }

      put(x, seatY + 2, z, upperDebris);
    }
  }

  function frameBlock(y, z) {
    const pattern = mod(y + z + phase, 3);

    if (pattern === 0 && y === 3) {
      return light;
    }

    if (pattern === 1) {
      return scorch;
    }

    return chitin;
  }

  const hatchBreak = mod(
    index + Math.floor(rScorch * 5),
    5
  );

  put(2, 3, 3, frameBlock(3, 3));
  put(2, 3, 5, frameBlock(3, 5));

  for (let y = 4; y <= 6; y += 1) {
    if (mod(y + hatchBreak + phase, 4) !== 0) {
      put(2, y, 3, frameBlock(y, 3));
    }

    if (mod(y + hatchBreak + phase + 1, 4) !== 0) {
      put(2, y, 5, frameBlock(y, 5));
    }
  }

  return {
    name: "Crashed Alien Drop Pod",
    seatY: seatY,
    anchors: {
      door: [2, 3, 4],
      furrowWest: [0, 2, 4],
      impact: [6, 2, 4],
      crown: [capX0, 9, capZ0]
    },
    interiors: [
      {
        min: [6, 3, 3],
        max: [8, 5, 5],
        kind: "vault"
      }
    ]
  };
}
